-- A1 Unit 1 re-plan (docs/a1-unit-1-welcome-town.md, owner-approved 2026-10-12).
-- RUN ONLY AFTER the branch with the rebuilt Unit 1 lessons is merged into main: these rows are published and live,
-- and the live site must not show the new titles/descriptions over the old lessons.
-- 1) Lesson 3 is now the numbers 1-20 + age lesson.
update curriculum_lessons set title = 'How Old Are You? Numbers 1-20', updated_at = now()
where ai_metadata->>'hub' = 'playground' and slot_cefr_level = 'A1' and slot_unit_number = '1' and slot_lesson_number = '3';
-- Lesson 6 is Game Day (the plan title).
update curriculum_lessons set title = 'Extra Practice: Game Day!', updated_at = now()
where ai_metadata->>'hub' = 'playground' and slot_cefr_level = 'A1' and slot_unit_number = '1' and slot_lesson_number = '6';
-- 2) The seven plans (description, grammar, vocabulary, phonics, blueprint_ref) from src/curriculum/roadmap/a1LessonPlans.ts.
set lock_timeout = '5s';
with units as (select * from jsonb_to_recordset('[{"u":"1","theme":"Welcome Town","title":"Welcome Town: Hello, Welcome Town!","goal":"Greet, introduce myself and a friend, and say how we feel"},{"u":"2","theme":"Jungle Adventure","title":"Jungle Adventure: What Can Animals Do?","goal":"Describe a jungle animal in 4 sentences (what it is, looks like, can, can''t) and ask \"Can it…?\""},{"u":"3","theme":"Space Mission","title":"Space Mission: Counting Quest","goal":"Count to 100 in tens, steer with directions and give a planet weather report"},{"u":"4","theme":"Food Festival","title":"Food Festival: I Like, I Don''t Like","goal":"Say what I like and like doing, ask a friend, and offer and accept food"},{"u":"5","theme":"Monster Academy","title":"Monster Academy: Faces, Feelings & Clothes","goal":"Describe a monster in 4 sentences: how it feels and why, its looks, family and clothes"},{"u":"6","theme":"Ocean Explorers","title":"Ocean Explorers: What Is It Doing?","goal":"Say what a sea animal is doing and where it lives, and find a hidden animal with yes/no questions"},{"u":"7","theme":"Superhero City","title":"Superhero City: Hero Helpers","goal":"Help a citizen: ask what''s wrong, offer help, say what I can do well and give one hero rule"},{"u":"8","theme":"Dinosaur Island","title":"Dinosaur Island: Bigger, Biggest, Long Ago","goal":"Compare two dinosaurs and say what one was like long ago"},{"u":"9","theme":"Magic Castle","title":"Magic Castle: Where Is It?","goal":"Describe a room: say what is where and whose things are"},{"u":"10","theme":"Future Tech Lab","title":"Future Tech Lab: How Does It Work?","goal":"Give a robot 3-step instructions and tell its day with times"}]'::jsonb) as x(u text, theme text, title text, goal text)),
plan as (select * from jsonb_to_recordset('[{"u": "1", "l": "1", "lt": "core", "sf": "Grammar", "o": "I can say hello and goodbye, say my name and ask \"What''s your name?\" \u2014 and read the first pages of Leo''s story.", "g": ["My name is\u2026", "What''s your name?"], "v": ["hello", "hi", "goodbye", "name"], "ph": ["h: hi, hop, hat \u2192 \"Hi! I am Pip.\"", "sight words: I, my, name, is", "twister: Happy Hen hops."], "r": [], "t": ["hello", "hi", "goodbye"], "vf": ["hello", "hi", "goodbye", "name"], "cg": "Greet someone new, say my name and ask theirs.", "sg": "Welcome Party (A1): say the line to open the door", "ev": "The child greets two arriving friends and asks their names in full sentences; reads story pages 1-3 aloud.", "fh": "Doors open on surprise guests; the child chooses who to greet first.", "hm": "Say hello and your name to two people at home and read them pages 1-3."}, {"u": "1", "l": "2", "lt": "core", "sf": "Vocabulary", "o": "I can ask \"How are you?\", say how I feel and say how a friend feels: \"I am tired. She is happy.\"", "g": ["How are you? I am\u2026", "He is / She is\u2026"], "v": ["fine", "happy", "sad", "tired", "hungry"], "ph": ["short a: sad, mad, had \u2192 \"Leo is sad.\"", "sight words: how, are, you, am", "twister: Sad Sam sits."], "r": ["My name is\u2026", "hello / goodbye", "Hello, My Name Is..."], "t": ["fine", "happy", "sad"], "vf": ["fine", "happy", "sad", "tired", "hungry", "My name is\u2026", "hello / goodbye"], "cg": "Ask friends how they are and tell someone how a friend feels.", "sg": "Feelings Survey (A1): ask 4 friends, report one", "ev": "The child asks 4 friends \"How are you?\" and reports one (\"She is tired.\"); reads pages 4-5.", "fh": "Situations make the feeling (\"I have no lunch!\" \u2192 hungry); a claw grabs the friend who is tired.", "hm": "Ask three people \"How are you?\" and draw their faces."}, {"u": "1", "l": "3", "lt": "core", "sf": "Reading/Listening", "o": "I can count and say the numbers 1-20, ask \"How old are you?\" and say my age: \"I am seven.\"", "g": ["How old are you? I am\u2026", "He / She is + number"], "v": ["eleven \u2026 twenty", "How old are you?", "birthday"], "ph": ["number words: six, ten \u2192 \"Bella is six.\" / \"I am ten.\"", "twister: Six silly snakes."], "r": ["numbers 1-10", "He is / She is\u2026", "What''s your name?", "Hello, My Name Is...", "Saying ''How Are You?''"], "t": ["eleven \u2026 twenty", "How old are you?", "birthday"], "vf": ["eleven \u2026 twenty", "How old are you?", "birthday", "numbers 1-10", "He is / She is\u2026", "What''s your name?"], "cg": "Ask and tell age, the second personal question after the name (Cambridge Starters Speaking Part 4).", "sg": "Birthday Balloons + Number Stepping Stones (model \u2192 memorise \u2192 age practice)", "ev": "The child says 1-20 in order and 5 random numbers, answers \"How old are you?\" in a full sentence and asks two friends.", "fh": "Birthday buzzer: guess each friend''s age; the child interviews Pip.", "hm": "Ask three family members \"How old are you?\" and count to 20 with them."}, {"u": "1", "l": "4", "lt": "core", "sf": "Speaking", "o": "I can introduce a friend \u2014 \"This is my friend Leo.\" \u2014 answer \"Nice to meet you!\" and hold a 6-line conversation.", "g": ["This is my friend\u2026", "Nice to meet you (too)"], "v": ["friend", "nice to meet you", "come in"], "ph": ["f / short u: fun, run, sun \u2192 \"Come on! It is fun!\"", "sight words: this, friend, nice, meet", "twister: Fun Fred finds a frog."], "r": ["How are you?", "He is / She is\u2026", "My name is\u2026", "Saying ''How Are You?''", "How Old Are You? Numbers 1-20"], "t": ["friend", "nice to meet you", "come in"], "vf": ["friend", "nice to meet you", "come in", "How are you?", "He is / She is\u2026", "My name is\u2026"], "cg": "Introduce a friend to someone new and have a short conversation.", "sg": "Guess My Friend (secret-card): ask, find, introduce; Welcome Song", "ev": "The child introduces two friends and holds a 6-line conversation with the teacher; reads pages 6-8.", "fh": "The child is the expert: Pip introduces the wrong friend and the child corrects him; Willow''s red hat surprise.", "hm": "Introduce a family member to a toy: \"This is my mum.\""}, {"u": "1", "l": "5", "lt": "storybook", "sf": "Reading/Listening", "o": "I can read the story \"Leo''s First Day\" with help, answer questions about it and act it out.", "g": ["all Unit 1 lines in the story"], "v": [], "ph": ["blend a whole sentence: The cap is on the cat.", "sight words: the, look, now, see"], "r": ["hello", "friend", "feelings", "cap, cat, red", "How Old Are You? Numbers 1-20", "This Is My Friend!"], "t": ["hello", "friend", "feelings"], "vf": ["hello", "friend", "feelings", "cap, cat, red"], "cg": "Read and understand a short story about meeting friends.", "sg": "Story video (stills film of the book with read-along subtitles) + Reader", "ev": "The child reads 4 pages alone, answers 4 yes/no questions and acts out pages 2-4 as Pip.", "fh": "Where is the cap? The child predicts, and it is on the cat!", "hm": "Read the book to your family."}, {"u": "1", "l": "6", "lt": "extra_practice", "sf": "Review", "o": "I can use all the Unit 1 language quickly and correctly, and read its sentences fast.", "g": ["My name is\u2026", "How are you?", "This is my friend\u2026"], "v": [], "ph": ["sight-word speed reading", "Twister Race: all four Unit 1 twisters"], "r": ["all Unit 1", "This Is My Friend!", "Storybook: Leo''s First Day"], "t": ["all Unit 1"], "vf": ["all Unit 1"], "cg": "Greet, ask and introduce without thinking; read the unit sentences fast.", "sg": "Word Board race (read the square, answer the question)", "ev": "Accuracy on the board race (not speed) and the Read & Do sentences.", "fh": "Board race with ladders and slides; a puppet friend arrives for a free chat.", "hm": "Play the greeting game with a family member."}, {"u": "1", "l": "7", "lt": "unit_review", "sf": "Review", "o": "I can hold a 6-line conversation (greet, name, how are you, introduce a friend, goodbye) and read the Unit 1 story sentences.", "g": ["all Unit 1"], "v": [], "ph": ["Unit 1 sounds", "read a story page aloud"], "r": ["all Unit 1", "Storybook: Leo''s First Day", "Extra Practice: Game Day!"], "t": ["all Unit 1"], "vf": ["all Unit 1"], "cg": "Meet someone new and talk for a minute; read a short story page.", "sg": "Boss Test (listening, reading yes/no, story gaps, speaking, reading aloud)", "ev": "Boss Test, 80 % in every part.", "fh": "Racing warm-up; teaser: a jungle sound and a monkey tail at the end (the Golden Compass story starts in Unit 2).", "hm": "Show your medal and introduce yourself."}]'::jsonb)
  as x(u text, l text, lt text, sf text, o text, g jsonb, v jsonb, ph jsonb, r jsonb, t jsonb, vf jsonb, cg text, sg text, ev text, fh text, hm text)),
p as (select plan.*, units.theme, units.title as unit_title, units.goal from plan join units using (u))
update curriculum_lessons c set
  description = p.o,
  grammar_pattern = (select string_agg(x, '; ') from jsonb_array_elements_text(p.g) x),
  vocabulary_list = p.v,
  phonics_focus = (select string_agg(x, ', ') from jsonb_array_elements_text(p.ph) x),
  ai_metadata = c.ai_metadata
    || case when c.ai_metadata ? 'previous_plan_2026_10_12' then '{}'::jsonb else jsonb_build_object('previous_plan_2026_10_12',
         jsonb_build_object('description', c.description, 'grammar_pattern', c.grammar_pattern, 'vocabulary_list', c.vocabulary_list,
           'phonics_focus', c.phonics_focus, 'unit_title', c.ai_metadata->'unit_title', 'blueprint_ref', c.ai_metadata->'blueprint_ref')) end
    || jsonb_build_object('unit_title', p.unit_title, 'blueprint_ref', jsonb_build_object(
         'id', coalesce(c.ai_metadata->'blueprint_ref'->'id', to_jsonb(c.id::text)),
         'adaptive_profile', coalesce(c.ai_metadata->'blueprint_ref'->'adaptive_profile', '{}'::jsonb),
         'title', c.title, 'objective', p.o, 'unit_theme', p.theme, 'unit_title', p.unit_title, 'unit_objective', p.goal,
         'lesson_type', p.lt, 'skill_focus', p.sf,
         'story_state', jsonb_build_object('arc', p.fh, 'theme', p.theme, 'characters', '[]'::jsonb),
         'unit_number', p.u::int, 'lesson_number', p.l::int, 'game_targets', p.t, 'homework_targets', p.t,
         'grammar_focus', p.g, 'phonics_focus', p.ph, 'pronunciation_focus', p.ph, 'review_targets', p.r,
         'vocabulary_focus', p.vf, 'communication_goal', p.cg, 'signature_game', p.sg, 'evidence', p.ev,
         'fun_hook', p.fh, 'home_mission', p.hm, 'plan_source', 'src/curriculum/roadmap/a1LessonPlans.ts (2026-10-12)')),
  updated_at = now()
from p
where c.ai_metadata->>'hub' = 'playground' and c.slot_cefr_level = 'A1'
  and c.slot_unit_number = p.u and c.slot_lesson_number = p.l
returning c.slot_unit_number, c.slot_lesson_number;
